'use strict';
// Cosmetic animation uses the visual clock and deterministic seeds, never world RNG.
const ambientOld={paintCachedMap,paintFires,drawCreature,damage,newWorld,restore};
let ambianceQuality=2,ambianceSamples=[],impactBursts=new Map();
try{const saved=localStorage.getItem('mam-effects');ambianceQuality=saved===null?(window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?1:2):Math.max(0,Math.min(2,Number(saved)||0));}catch{}
const ambianceNoise=n=>{const value=Math.sin(n*127.1+311.7)*43758.5453;return value-Math.floor(value);};
function animatedScenery(x,y,t){return ambianceQuality>0&&(t.obj===0||t.obj===1)&&((x*13+y*7)%47===0);}
function ambianceVisible(x,y,pad=3){const s=base*zoom,ox=(cw-W*s)/2+panX,oy=(ch-H*s)/2+panY;return x*s+ox>-pad*s&&y*s+oy>-pad*s&&x*s+ox<cw+pad*s&&y*s+oy<ch+pad*s;}
function refreshAmbianceSamples(){ambianceSamples=[];for(let i=0;i<N;i++){const t=grid[i],x=i%W,y=Math.floor(i/W);if(animatedScenery(x,y,t))ambianceSamples.push({i,x,y,tree:true});else if(t.t===0&&i%31===0)ambianceSamples.push({i,x,y,tree:false});}}
function ambianceDot(x,y,r,color){ctx.fillStyle=color;ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fill();}
paintCachedMap=function(){if(mapDirty||!ambianceSamples.length)refreshAmbianceSamples();const result=ambientOld.paintCachedMap();if(!ambianceQuality)return result;const time=animationTime();let water=0;
 for(const sample of ambianceSamples){const {i,x,y,tree}=sample;if(!ambianceVisible(x,y))continue;const t=grid[i];if(tree){if(typeof paintDepthWorld==='function')continue;if(!animatedScenery(x,y,t))continue;ctx.save();ctx.translate(x+.5,y+.65);ctx.rotate(Math.sin(time*1.3+i)*.025);ctx.translate(-x-.5,-y-.65);if(!(typeof paintBiomeObject==='function'&&paintBiomeObject(ctx,x,y,t))&&spriteReady)atlasTo(ctx,sprite,t.obj,4,x+.5,y+.65,2.25);ctx.restore();if(ambianceQuality===2){const phase=(time*.18+ambianceNoise(i))%1;ctx.save();ctx.globalAlpha=Math.sin(phase*Math.PI)*.5;ctx.fillStyle='#c4d77a';ctx.fillRect(x+.4+Math.sin(phase*8+i)*.35,y-.2+phase*1.5,.09,.05);ctx.restore();}}else if(t.t===0&&water++<(ambianceQuality===2?100:30)){const phase=(time*.35+ambianceNoise(i))%1;ctx.save();ctx.globalAlpha=Math.sin(phase*Math.PI)*.25;ctx.strokeStyle='#bce9ed';ctx.lineWidth=.035;ctx.beginPath();ctx.ellipse(x+.5,y+.5,.1+phase*.4,.04+phase*.12,0,0,Math.PI*2);ctx.stroke();ctx.restore();}}
 return result;};
paintFires=function(){let decorated=0;for(const i of burningTiles){if(!grid[i].fire)continue;const x=i%W+.5,y=Math.floor(i/W)+.5;if(!ambianceVisible(x,y))continue;drawSprite(12,x,y,1.9+Math.sin(visualTime*7+i)*.12);if(!ambianceQuality||decorated++>=(ambianceQuality===2?40:12))continue;ctx.save();ambianceDot(x,y,.6,'#ff952c25');for(let k=0;k<(ambianceQuality===2?4:2);k++){const phase=(visualTime*.45+k*.25+ambianceNoise(i))%1;ctx.globalAlpha=(1-phase)*.38;ambianceDot(x+Math.sin(i+k+phase*3)*.25,y-.5-phase*1.6,.12+phase*.25,'#b4a79a');}if(ambianceQuality===2)for(let k=0;k<3;k++){const phase=(visualTime*.8+k/3+ambianceNoise(i))%1;ctx.globalAlpha=1-phase;ambianceDot(x+Math.sin(i+k+phase*5)*.3,y-phase*1.4,.035,'#ffd078');}ctx.restore();}};
damage=function(e,value){const before=e.hp;ambientOld.damage(e,value);if(!ambianceQuality||before-e.hp<3)return;const prior=impactBursts.get(e.id);if(prior&&visualTime-prior.born<.18)return;if(impactBursts.size>=64)impactBursts.delete(impactBursts.keys().next().value);impactBursts.set(e.id,{x:e.x,y:e.y,born:visualTime,seed:e.id+Math.floor(visualTime*10)});};
drawCreature=function(e,bob){if(ambianceQuality&&ambianceVisible(e.x,e.y)){const motion=motionFor(e),velocity=Math.hypot(motion.vx,motion.vy);if(velocity>.15&&(ambianceQuality===2||e.id%3===0)){const wet=e.sailing&&grid[idx(e.x,e.y)].t===0,cold=typeof biomeAt==='function'&&biomeAt(e.x,e.y)==='tundra';ctx.save();for(let k=0;k<3;k++){const phase=(motion.steps*1.7+k/3)%1;ctx.globalAlpha=(1-phase)*.22;ambianceDot(e.x-motion.vx/velocity*phase*.7+Math.sin(e.id+k)*.08,e.y-motion.vy/velocity*phase*.7+.15,.035+phase*.075,wet?'#caefff':cold?'#e7f4fb':'#d6b788');}ctx.restore();}}
 ambientOld.drawCreature(e,bob);
 const impact=impactBursts.get(e.id);if(!impact)return;const age=visualTime-impact.born;if(age>.55){impactBursts.delete(e.id);return;}if(!ambianceQuality||!ambianceVisible(impact.x,impact.y))return;ctx.save();ctx.globalAlpha=1-age/.55;for(let k=0;k<(ambianceQuality===2?8:4);k++){const angle=ambianceNoise(impact.seed+k)*Math.PI*2,r=age*(1.2+ambianceNoise(k+impact.seed)*1.2);ambianceDot(impact.x+Math.cos(angle)*r,impact.y-.5+Math.sin(angle)*r,.04,'#ffe5af');}ctx.restore();};
function setAmbianceQuality(value){if(!Number.isInteger(value)||value<0||value>2)throw Error('Mức hiệu ứng không hợp lệ.');ambianceQuality=value;mapDirty=true;ambianceSamples=[];impactBursts.clear();try{localStorage.setItem('mam-effects',String(value));}catch{}renderAmbianceButton();return value;}
const ambianceButton=document.createElement('button');ambianceButton.id='ambiance-toggle';ambianceButton.onclick=()=>setAmbianceQuality((ambianceQuality+1)%3);function renderAmbianceButton(){ambianceButton.textContent='✨ Hiệu ứng: '+['Tắt','Nhẹ','Đầy đủ'][ambianceQuality];ambianceButton.title='Nhấn để đổi mức hiệu ứng';ambianceButton.setAttribute('aria-label',ambianceButton.textContent);}
const ambianceAnchor=$('era-open');if(ambianceAnchor?.parentNode)ambianceAnchor.parentNode.append(ambianceButton);else $('viewport').append(ambianceButton);renderAmbianceButton();
newWorld=function(...args){const result=ambientOld.newWorld(...args);impactBursts.clear();ambianceSamples=[];return result;};restore=function(...args){const result=ambientOld.restore(...args);impactBursts.clear();ambianceSamples=[];return result;};
window.mamWorld={...window.mamWorld,setAmbianceQuality,getAmbiance:()=>({quality:ambianceQuality,impacts:impactBursts.size,samples:ambianceSamples.length})};
